      + 'Q12.69 6.5 13.29 6.71Q13.89 6.91 14.34 7.25Q14.79 7.58 15.11 8Q15.43 8.42 15.65 8.85L13.56 9.93'
      + 'Q13.48 9.75 13.33 9.57Q13.19 9.38 12.96 9.24Q12.73 9.09 12.43 8.99Q12.12 8.9 11.73 8.9Q11.13 8.9 10.7 9.16'
      + 'Q10.28 9.43 10.28 9.96Q10.28 10.31 10.43 10.58Q10.58 10.85 10.92 11.03Q11.27 11.21 11.82 11.32'
